    assertEquals("image4.emf", handler.filenames.get(6));
    assertEquals("Microsoft_Office_Excel_Worksheet1.xlsx", handler.filenames.get(7));
    assertEquals("image5.emf", handler.filenames.get(8));
    // But we do know their types
