    assertEquals("EX", metadata.get(Office.MAPI_SENT_BY_SERVER_TYPE));
    assertEquals("NOTE", metadata.get(Office.MAPI_MESSAGE_CLASS));
    assertEquals("Jukka Zitting", metadata.get(Message.MESSAGE_FROM_NAME));
